<script setup lang="ts">
import {ref,onMounted,computed,watch,nextTick} from 'vue'
import PolicySection from './PolicySection.vue'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>}>()
const rows=ref<Row[]>([]),users=ref<Row[]>([]),nodes=ref<Row[]>([]),clients=ref<Row[]>([]),editing=ref<Row|null>(null),busy=ref(false),error=ref(''),notice=ref('')
const groups=ref<Row[]>([]),rules=ref<string[]>([]),basic=ref<Row>({}),dns=ref<Row>({}),native=ref('{}'),tab=ref('routing'),sourceDirty=ref(false),visualDirty=ref(false)
const groupDraft=ref<Row|null>(null),groupIndex=ref(-1),ruleIndex=ref(-1),rule=ref({type:'DOMAIN-SUFFIX',value:'',target:'PROXY',noResolve:false}),ruleOpen=ref(false),search=ref(''),page=ref(1)
const importOpen=ref(false),importSource=ref(''),imported=ref<Row|null>(null),importAck=ref(false),importSections=ref(['basic','dns','groups','rules']),preview=ref<Row|null>(null),previewClient=ref('mihomo'),routingFocus=ref('groups')
const sectionEditor=ref<{pending:boolean}|null>(null)
function chooseTab(value:string){if(sectionEditor.value?.pending){error.value='请先应用或取消分区 JSON 修改';return};tab.value=value}
let hydrating=false
watch([groups,rules,basic,dns],()=>{if(!hydrating&&editing.value)visualDirty.value=true},{deep:true,flush:'sync'})
watch(()=>editing.value?.source,()=>{if(!hydrating&&editing.value)sourceDirty.value=true},{flush:'sync'})
watch(search,()=>page.value=1)
const refs=computed(()=>Array.from(new Set(['ALL','family:ipv4','family:ipv6','DIRECT','REJECT','PROXY',...groups.value.map(g=>g.name),...nodes.value.filter(n=>!n.delete_requested_at).map(n=>'node:'+n.id),...nodes.value.map(n=>'protocol:'+n.kind)])))
const filtered=computed(()=>rules.value.map((value,index)=>({value,index})).filter(r=>!search.value||r.value.toLowerCase().includes(search.value.toLowerCase())))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/25)))
const visibleRules=computed(()=>filtered.value.slice((Math.min(page.value,pages.value)-1)*25,Math.min(page.value,pages.value)*25))
const groupRefs=computed(()=>Array.from(new Set([...refs.value,...(groupDraft.value?.proxies??[])])).filter(r=>r!==groupDraft.value?.name))
const kinds=['DOMAIN','DOMAIN-SUFFIX','DOMAIN-KEYWORD','IP-CIDR','IP-CIDR6','SRC-IP-CIDR','DST-PORT','SRC-PORT','NETWORK','PROCESS-NAME','PROCESS-PATH','GEOIP','GEOSITE','MATCH']
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v))
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function load(){[rows.value,users.value,nodes.value,clients.value]=await Promise.all(['client-policies','proxy-users','live','client-catalog'].map(p=>props.api(p)))}
onMounted(()=>void run(load))
function hydrate(p:Row,source:string){hydrating=true;basic.value=clone(p.basic??{});dns.value=clone(p.dns??{});groups.value=clone(p['proxy-groups']??[]);rules.value=clone(p.rules??[]);if(editing.value)editing.value.source=source;hydrating=false;visualDirty.value=false;sourceDirty.value=false;groupDraft.value=null;ruleOpen.value=false;page.value=1}
async function factory(global=false){const result=await props.api('client-policies/default');if(!editing.value||global){const old=global?rows.value.find(r=>!r.user_id&&r.client_id==='all'):undefined;editing.value=old?clone(old):{name:result.name??'Mihomo Max 默认模板',user_id:'',client_id:'all',version:0,source:''}};if(global&&editing.value)editing.value.name=result.name;hydrate(result.policy,result.source);native.value=JSON.stringify(result.native_options??{},null,2);tab.value='routing';notice.value=(result.notes??[]).join('；')}
function create(){void run(async()=>{editing.value=null;await factory()})}
function edit(row:Row){void run(async()=>{editing.value=clone(row);native.value=JSON.stringify(row.native_options??{},null,2);await parse();tab.value='routing'})}
async function serialize(){if(!editing.value)return;const r=await props.api('client-policies/parse','POST',{policy:{basic:basic.value,dns:dns.value,'proxy-groups':groups.value,rules:rules.value}});hydrating=true;editing.value.source=r.source;hydrating=false;visualDirty.value=false;sourceDirty.value=false}
async function parse(){if(!editing.value)return;const r=await props.api('client-policies/parse','POST',{source:editing.value.source});hydrate(r.policy,r.source)}
async function prepare(){if(sectionEditor.value?.pending)throw new Error('请先应用或取消分区 JSON 修改');if(groupDraft.value||ruleOpen.value)throw new Error('请先保存或取消正在编辑的组/规则');if(visualDirty.value&&sourceDirty.value)throw new Error('表单与 YAML 均已修改，请选择同步方向后继续');if(visualDirty.value||!editing.value?.source)await serialize();else if(sourceDirty.value)await parse()}
function save(){void run(async()=>{await prepare();const v=editing.value!;await props.api('client-policies'+(v.id?'/'+v.id:''),v.id?'PUT':'POST',{name:v.name,user_id:v.user_id??'',client_id:v.client_id,source:v.source,native_options:JSON.parse(native.value),version:v.version});editing.value=null;preview.value=null;notice.value='已保存，下一次更新订阅自动带入四个分区的设置';await load()})}
function close(){editing.value=null;importSource.value='';imported.value=null;importOpen.value=false;preview.value=null;error.value=''}
function remove(row:Row){if(!window.confirm('删除策略 '+row.name+'？订阅将使用下一层策略。'))return;void run(async()=>{await props.api('client-policies/'+row.id,'DELETE');await load()})}
function label(r:string){if(r==='ALL')return '全部已授权节点';if(r==='family:ipv4')return '仅 IPv4 节点';if(r==='family:ipv6')return '仅 IPv6 节点';if(r.startsWith('protocol:'))return r.slice(9)+' · 动态协议';const n=nodes.value.find(n=>'node:'+n.id===r);return n?`${n.name} · ${n.kind}`:r}
function scrollEditor(name:string){void nextTick(()=>{const el=document.querySelector('[aria-label="'+name+'"]');if(el instanceof HTMLElement&&el.scrollIntoView)el.scrollIntoView({behavior:'smooth',block:'center'})})}
function editGroup(i:number){scrollEditor('策略组编辑');groupIndex.value=i;groupDraft.value=i<0?{name:'新策略组'+(groups.value.length+1),type:'select',proxies:['ALL'],interval:300,tolerance:50,url:'https://www.gstatic.com/generate_204',lazy:true}:clone(groups.value[i])}
function replaceRef(from:string,to:string){for(const g of groups.value)g.proxies=g.proxies.map((r:string)=>r===from?to:r);rules.value=rules.value.map(l=>{const p=l.split(',');const i=p[0]==='MATCH'?1:2;if(p[i]===from)p[i]=to;return p.join(',')});for(const k of ['nameserver','direct-nameserver','proxy-server-nameserver'])if(Array.isArray(dns.value[k]))dns.value[k]=dns.value[k].map((s:string)=>s.endsWith('#'+from)?s.slice(0,-from.length)+to:s)}
function saveGroup(){const g=groupDraft.value!;if(!g.name.trim()||groups.value.some((v,i)=>i!==groupIndex.value&&v.name===g.name)){error.value='组名不能为空或重复';return};if(g.proxies.includes(g.name)){error.value='组不能引用自己';return};if(groupIndex.value<0)groups.value.push(clone(g));else{const old=groups.value[groupIndex.value]!.name;groups.value[groupIndex.value]=clone(g);if(old!==g.name)replaceRef(old,g.name)};groupDraft.value=null;error.value=''}
function deleteGroup(i:number){const name=groups.value[i]!.name;if(groups.value.some((g,j)=>j!==i&&g.proxies.includes(name))||rules.value.some(l=>{const p=l.split(',');return p[p[0]==='MATCH'?1:2]===name})||Object.values(dns.value).some(v=>Array.isArray(v)&&v.some(s=>typeof s==='string'&&s.endsWith('#'+name)))){error.value='该组仍被组、规则或 DNS 引用，请先修改引用';return};groups.value.splice(i,1)}
function moveMember(i:number,d:number){const a=groupDraft.value!.proxies,j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]]}
function editRule(i=-1){scrollEditor('规则编辑');ruleIndex.value=i;const p=i<0?['DOMAIN-SUFFIX','','PROXY']:rules.value[i]!.split(',');rule.value={type:p[0]!,value:p[0]==='MATCH'?'':p[1]!,target:p[p[0]==='MATCH'?1:2]!,noResolve:p.at(-1)==='no-resolve'};ruleOpen.value=true}
function saveRule(){const r=rule.value;if(r.type!=='MATCH'&&!r.value.trim()){error.value='请输入匹配内容';return};const line=r.type==='MATCH'?'MATCH,'+r.target:[r.type,r.value.trim(),r.target,...(r.noResolve?['no-resolve']:[])].join(',');if(ruleIndex.value>=0)rules.value.splice(ruleIndex.value,1);if(r.type==='MATCH'){rules.value=rules.value.filter(s=>!s.startsWith('MATCH,'));rules.value.push(line)}else{const last=rules.value.at(-1)?.startsWith('MATCH,')?rules.value.length-1:rules.value.length;rules.value.splice(ruleIndex.value>=0?Math.min(ruleIndex.value,last):last,0,line)};ruleOpen.value=false;error.value=''}
function moveRule(i:number,d:number){const j=i+d;if(j<0||j>=rules.value.length||rules.value[i]!.startsWith('MATCH,')||rules.value[j]!.startsWith('MATCH,'))return;[rules.value[i],rules.value[j]]=[rules.value[j]!,rules.value[i]!]}
async function readFile(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>131072){error.value='文件最多 128 KiB';return};importSource.value=await f.text();imported.value=null}
function inspectImport(){void run(async()=>{imported.value=await props.api('client-policies/import','POST',{source:importSource.value});importAck.value=false})}
function applyImport(){void run(async()=>{const data=imported.value!;if(importSections.value.includes('rules')&&data.unsupported_rules>0)throw new Error('存在无法等价转换的规则，请先改写原配置，或取消导入规则分区');if(data.warnings?.length&&!importAck.value)throw new Error('请先核对并确认导入差异');const p=clone(data.policy),map=new Map<string,string>();for(const m of data.mappings??[]){if(!m.reference)throw new Error('请映射节点：'+m.name);map.set(m.name,m.reference)};for(const r of data.unresolved??[])if(!map.has(r))throw new Error('未映射引用：'+r);const ref=(r:string)=>map.get(r)??r;p['proxy-groups']=(p['proxy-groups']??[]).map((g:Row)=>({...g,proxies:g.proxies.map(ref)}));p.rules=(p.rules??[]).map((l:string)=>{const a=l.split(','),i=a[0]==='MATCH'?1:2;a[i]=ref(a[i]!);return a.join(',')});for(const k of ['nameserver','direct-nameserver','proxy-server-nameserver'])if(Array.isArray(p.dns?.[k]))p.dns[k]=p.dns[k].map((s:string)=>{const i=s.indexOf('#');return i<0?s:s.slice(0,i+1)+ref(s.slice(i+1))});if(importSections.value.includes('basic'))basic.value=p.basic??{};if(importSections.value.includes('dns'))dns.value=p.dns??{};if(importSections.value.includes('groups'))groups.value=p['proxy-groups']??[];if(importSections.value.includes('rules'))rules.value=p.rules??[];if(importSections.value.includes('native')&&Object.keys(data.native_options??{}).length)native.value=JSON.stringify({...JSON.parse(native.value),...data.native_options},null,2);await serialize();importOpen.value=false;importSource.value='';imported.value=null;notice.value='已应用到草稿，尚未保存或改变订阅'})}
function compile(){void run(async()=>{await prepare();preview.value=await props.api('client-policies/preview','POST',{source:editing.value!.source,client_id:previewClient.value,native_options:JSON.parse(native.value)})})}
</script>
<template><section class="panel publish-card"><div class="section-heading"><div><h2>客户端配置工作区</h2><p class="muted">基础、DNS、策略组和规则独立编辑。用户专用优先；客户端专用覆盖通用转换。</p></div><div class="row-actions"><button class="secondary" :disabled="busy" @click="run(()=>factory(true))">使用文件模板设为全局默认</button><button class="primary" :disabled="busy" @click="create">＋ 添加策略</button></div></div><p v-if="error&&!editing" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><div class="policy-index"><article v-for="r in rows" :key="r.id"><div><strong>{{r.name}}</strong><small>{{users.find(u=>u.id===r.user_id)?.name??'全局默认'}} · {{clients.find(c=>c.id===r.client_id)?.name??'通用自动转换'}} · v{{r.version}}</small></div><div><button class="text-button" @click="edit(r)">编辑</button><button class="text-button danger" @click="remove(r)">删除</button></div></article></div></section>
<form v-if="editing" role="dialog" aria-label="客户端分流策略" class="policy-workspace panel" @submit.prevent="save"><div class="section-heading"><div><span class="eyebrow">CLIENT CONFIGURATION</span><h2>{{editing.id?'编辑':'新建'}} · {{editing.name}}</h2></div><button type="button" class="secondary" @click="close">关闭</button></div><p v-if="error" class="error" role="alert">{{error}}</p><div class="fields"><label>名称<input v-model="editing.name" required maxlength="100"></label><label>所属用户<select v-model="editing.user_id"><option value="">全局默认 / 共享订阅</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label>客户端<select v-model="editing.client_id"><option value="all">通用（按客户端自动转换）</option><option v-for="c in clients.filter(c=>c.full_config)" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div><nav class="subnav"><button type="button" :class="{active:tab==='basic'}" @click="chooseTab('basic')">基础配置</button><button type="button" :class="{active:tab==='dns'}" @click="chooseTab('dns')">DNS</button><button type="button" :class="{active:tab==='routing'}" @click="chooseTab('routing')">策略组 {{groups.length}} / 规则 {{rules.length}}</button><button type="button" :class="{active:tab==='preview'}" @click="chooseTab('preview')">原生覆盖 / 转换预览</button></nav>
<div class="row-actions tools"><button type="button" class="secondary" @click="importOpen=!importOpen">导入 YAML / JSON / CONF</button><button type="button" class="text-button" :disabled="busy" @click="run(()=>factory())">载入默认模板到草稿</button><span class="muted">修改只在保存后影响订阅</span></div>
<section v-if="importOpen" class="panel import-panel"><h3>识别并选择导入分区</h3><input type="file" accept=".yaml,.yml,.json,.conf,.ini,.txt" aria-label="导入配置文件" @change="readFile"><label>完整配置或配置片段<textarea v-model="importSource" rows="8" maxlength="131072" spellcheck="false" class="native-preview"></textarea></label><button type="button" class="secondary" :disabled="busy||!importSource.trim()" @click="inspectImport">识别配置内容</button><template v-if="imported"><p class="notice">{{imported.format}} · {{imported.policy['proxy-groups']?.length??0}} 个组 / {{imported.policy.rules?.length??0}} 条规则</p><div class="choice-list"><label v-for="[k,label] in [['basic','基础配置'],['dns','DNS'],['groups','策略组'],['rules','规则'],['native','本客户端原生 DNS / 日志覆盖（需核对旧标签）']]" :key="k"><input v-model="importSections" type="checkbox" :value="k">{{label}}</label></div><div v-for="m in imported.mappings" :key="m.name" class="mapping-row"><span>{{m.name}} · {{m.protocol}}</span><select v-model="m.reference" :aria-label="'映射 '+m.name"><option value="">请选择节点或动态协议</option><option v-for="r in refs.filter(r=>r==='ALL'||r.startsWith('node:')||r.startsWith('protocol:')||r.startsWith('family:'))" :key="r" :value="r">{{label(r)}}</option></select></div><div v-for="r in imported.unresolved.filter((r:string)=>!imported!.mappings.some((m:Row)=>m.name===r))" :key="r"><span>未匹配：{{r}}</span><button type="button" @click="imported.mappings.push({name:r,protocol:'',reference:''})">手动映射</button></div><ul class="import-warnings"><li v-for="(w,i) in imported.warnings" :key="i">{{w}}</li></ul><label><input v-model="importAck" type="checkbox">已核对字段差异和节点映射</label><button type="button" class="primary" :disabled="busy||!importSections.length" @click="applyImport">应用所选分区到草稿</button></template></section>
<PolicySection ref="sectionEditor" v-if="tab==='basic'" kind="basic" v-model="basic"/><PolicySection ref="sectionEditor" v-if="tab==='dns'" kind="dns" v-model="dns"/>
<nav v-if="tab==='routing'" class="routing-mobile-tabs"><button type="button" :class="{active:routingFocus==='groups'}" @click="routingFocus='groups'">策略组 {{groups.length}}</button><button type="button" :class="{active:routingFocus==='rules'}" @click="routingFocus='rules'">规则 {{rules.length}}</button></nav><div v-if="tab==='routing'" class="routing-columns" :data-focus="routingFocus"><section class="routing-pane"><div class="section-heading"><h3>策略组 <small>{{groups.length}}</small></h3><button type="button" class="secondary" @click="editGroup(-1)">＋ 创建组</button></div><p class="muted">动态引用只匹配获授权节点；成员顺序决定默认选择。</p><section v-if="groupDraft" class="inline-editor" aria-label="策略组编辑"><h4>编辑策略组</h4><label>组名<input v-model="groupDraft.name" aria-label="组名"></label><label>组类型<select v-model="groupDraft.type"><option>select</option><option>url-test</option><option>fallback</option><option>load-balance</option></select></label><div v-if="groupDraft.type!=='select'" class="fields"><label>测速间隔<input v-model.number="groupDraft.interval" type="number" min="1" max="86400"></label><label>测试 URL<select v-model="groupDraft.url"><option>https://www.gstatic.com/generate_204</option><option>https://cp.cloudflare.com/generate_204</option></select></label><label>容差<input v-model.number="groupDraft.tolerance" type="number" min="0" max="10000"></label></div><div class="choice-list member-choices"><label v-for="r in groupRefs" :key="r"><input v-model="groupDraft.proxies" type="checkbox" :value="r">{{label(r)}}</label></div><ol class="member-order"><li v-for="(r,i) in groupDraft.proxies" :key="r+i"><span>{{label(r)}}</span><button type="button" class="text-button" :disabled="i===0" @click="moveMember(Number(i),-1)">↑</button><button type="button" class="text-button" :disabled="i===groupDraft.proxies.length-1" @click="moveMember(Number(i),1)">↓</button></li></ol><button type="button" class="primary" @click="saveGroup">保存此组到草稿</button><button type="button" class="secondary" @click="groupDraft=null">取消编辑组</button></section><article v-for="(g,i) in groups" :key="g.name+'-'+i" class="group-card"><div class="section-heading"><strong>{{g.name}}</strong><small>{{g.type}}</small></div><p>{{g.proxies.length}} 个引用 · {{g.proxies.slice(0,3).map(label).join(' / ')}}{{g.proxies.length>3?' …':''}}</p><button type="button" class="text-button" @click="editGroup(i)">编辑组</button><button type="button" class="text-button danger" @click="deleteGroup(i)">删除组</button></article></section>
<section class="routing-pane"><div class="section-heading"><h3>规则 <small>{{rules.length}}</small></h3><button type="button" class="secondary" @click="editRule()">＋ 创建规则</button></div><label>搜索规则<input v-model="search" placeholder="域名、目标组或类型"></label><section v-if="ruleOpen" class="inline-editor" aria-label="规则编辑"><h4>{{ruleIndex<0?'创建':'编辑第 '+(ruleIndex+1)+' 条'}}规则</h4><label>规则类型<select v-model="rule.type"><option v-for="t in kinds" :key="t">{{t}}</option></select></label><label v-if="rule.type!=='MATCH'">匹配内容<input v-model="rule.value" aria-label="规则匹配内容"></label><label>目标<select v-model="rule.target"><option v-for="t in refs.filter(r=>r!=='ALL')" :key="t" :value="t">{{label(t)}}</option></select></label><label v-if="['IP-CIDR','IP-CIDR6','GEOIP'].includes(rule.type)"><input v-model="rule.noResolve" type="checkbox">no-resolve</label><button type="button" class="primary" @click="saveRule">保存此规则到草稿</button><button type="button" class="secondary" @click="ruleOpen=false">取消编辑规则</button></section><ol class="rule-list"><li v-for="r in visibleRules" :key="r.index"><span class="rule-number">{{r.index+1}}</span><code>{{r.value}}</code><div class="rule-actions"><button type="button" class="text-button" :aria-label="'编辑规则 '+(r.index+1)" @click="editRule(r.index)">编辑</button><button type="button" class="text-button" :disabled="r.index===0||r.value.startsWith('MATCH,')" @click="moveRule(r.index,-1)">↑</button><button type="button" class="text-button" :disabled="r.index===rules.length-1||rules[r.index+1]?.startsWith('MATCH,')" @click="moveRule(r.index,1)">↓</button><button type="button" class="text-button danger" :aria-label="'删除规则 '+(r.index+1)" @click="rules.splice(r.index,1)">删除</button></div></li></ol><div class="pagination"><button type="button" class="secondary" :disabled="page<=1" @click="page--">上一页</button><span>{{Math.min(page,pages)}} / {{pages}} · 每页 25 条</span><button type="button" class="secondary" :disabled="page>=pages" @click="page++">下一页</button></div></section></div>
<section v-if="tab==='preview'" class="panel"><h3>按客户端生成预览</h3><p class="muted">预览使用不可用的本地节点占位，不含身份凭据。实际订阅仅发布已授权且运行中的兼容节点。</p><label>预览客户端<select v-model="previewClient"><option v-for="c in clients.filter(c=>c.full_config)" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button type="button" class="secondary" :disabled="busy" @click="compile">转换预览</button><template v-if="preview"><ul><li v-for="(w,i) in preview.warnings" :key="i">{{w}}</li></ul><pre class="native-preview">{{preview.text??JSON.stringify(preview.config,null,2)}}</pre></template><label>各客户端原生覆盖 JSON<textarea v-model="native" rows="14" class="native-preview" spellcheck="false"></textarea></label><p class="form-note">分别使用 mihomo / sing-box / xray / shadowrocket-config 键。订阅关联模板最后生效。小火箭的规则配置与节点订阅分开导入，规则目标按应用当前 PROXY 选择运行。</p></section>
<details class="source-editor"><summary>完整策略源 · YAML / JSON</summary><div class="row-actions"><button type="button" class="secondary" :disabled="busy" @click="run(serialize)">表单 → YAML</button><button type="button" class="secondary" :disabled="busy" @click="run(parse)">YAML → 表单</button></div><label>通用策略源（基础分区独立，保存此内容）<textarea v-model="editing.source" rows="18" class="native-preview" maxlength="32768" spellcheck="false"></textarea></label><p class="muted">basic、dns、proxy-groups、rules 独立。完整客户端文件请使用导入识别。</p></details><footer class="workspace-footer"><span>{{visualDirty||sourceDirty?'有未保存修改':'草稿已同步'}}</span><div class="row-actions"><button type="button" class="secondary" @click="close">取消</button><button class="primary" :disabled="busy">保存策略</button></div></footer></form></template>
