px;overflow:auto}.member-order{padding:0;list-style:none}.member-order li{display:flex;align-items:center;font-size:12px;gap:8px}.member-order span{flex:1;overflow-wrap:anywhere}.rule-list{padding:0;list-style:none;margin:18px 0}.rule-list li{display:grid;grid-template-columns:28px minmax(0,1fr);gap:7px;padding:13px 0;border-bottom:1px solid var(--border)}.rule-number{color:var(--muted);font-size:11px;padding-top:2px}.rule-list code{font-size:12px;overflow-wrap:anywhere;line-height:1.6}.rule-actions{grid-column:2;display:flex;gap:8px}.pagination{display:flex;gap:12px;align-items:center;justify-content:space-between;font-size:12px}.mapping-row{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:12px 0;font-size:12px}.import-warnings{max-height:220px;overflow:auto;font-size:12px;line-height:1.8}.source-editor{margin:24px 0}.workspace-footer{position:sticky;bottom:0;padding:16px 0;display:flex;align-items:center;justify-content:space-between;background:var(--panel);border-top:1px solid var(--border);z-index:2;font-size:12px}.import-panel{margin:18px 0}.eyebrow{color:var(--accent);font-size:10px;letter-spacing:2px}pre{max-height:480px;overflow:auto}@media(max-width:900px){.routing-mobile-tabs{display:flex;gap:10px;margin-top:20px}.routing-columns{grid-template-columns:1fr}.routing-columns[data-focus=groups]>.routing-pane:last-child{display:none}.routing-columns[data-focus=rules]>.routing-pane:first-child{display:none}.section-heading{flex-wrap:wrap}}@media(max-width:540px){.mapping-row{grid-template-columns:1fr}.workspace-footer{gap:8px;flex-wrap:wrap}.tools>span{width:100%}.policy-workspace{padding:16px}.pagination{gap:6px}}</style>
